constraints:
1 ≤ n ≤ 10^{6}
0 ≤ arr_{i} ≤ 10^{18}

expected time complexity: O(n)
expected auxiliary space: O(n)

standard_solution_code:
class Solution:

	def nextLargerElement(self, arr, n):
		stack = []
		res = [-1 for _ in range(n)]
		for i in range(n - 1, -1, -1):
			while stack != [] and stack[-1] <= arr[i]:
				stack.pop()
			if stack == []:
				res[i] = -1
			else:
				res[i] = stack[-1]
			stack.append(arr[i])
		return res
